def H_a(z):
    return z**2 * np.sinh(0.5 * z) + 4 * z * np.cosh(z) - 2 * z - 1

def H_a_prime(z):
    return 2 * z * np.sinh(0.5 * z) + 0.5 * z**2 * np.cosh(0.5 * z) + 4 * np.cosh(z) + 4 * z * np.sinh(z) - 2

def integrand(t, R):
    z = R * np.exp(1j * t)
    return (H_a_prime(z) / H_a(z)) * (1j * z)

def get_N(R):
    res, _ = quad(lambda t: np.real(integrand(t, R)), 0, 2 * np.pi)
    return int(round(res / (2 * np.pi)))

