from itertools import combinations

def get_rm_basis(r, m):
    n = 2**m
    basis = []
    for i in range(r + 1):
        for combo in combinations(range(m), i):
            vec = np.ones(n, dtype=int)
            for idx in range(n):
                for bit in combo:
                    if not (idx & (1 << bit)):
                        vec[idx] = 0
            basis.append(vec)
    return np.array(basis)

def solve():
    total_score = 0
    for m in [4, 5]:
        for r1 in range(m - 1):
            for r2 in range(r1 + 1, m - 1):
                rm1 = get_rm_basis(r1, m)
                rm2 = get_rm_basis(r2, m)
                even8_basis = [c for c in rm2 if np.sum(c) % 8 == 0]
                full_basis = np.vstack([rm1, even8_basis])
                # Use Gaussian elimination to find basis and dimension
                mat = np.unique(full_basis, axis=0)
                for i in range(len(mat)):
                    pivot = np.argmax(mat[i:, :])
                    if mat[i, pivot] == 0: continue
                    for j in range(len(mat)):
                        if i != j and mat[j, pivot]: mat[j] = (mat[j] + mat[i]) % 2
                basis = mat[np.any(mat, axis=1)]
                k = len(basis)
                min_w = 2**m
                count = 0
                for i in range(1, 1 << k):
                    c = np.zeros(2**m, dtype=int)
                    for j in range(k):
                        if (i >> j) & 1: c = (c + basis[j]) % 2
                    w = np.sum(c)
                    if w < min_w: min_w, count = w, 1
                    elif w == min_w: count += 1
                total_score += k * min_w * count
    return total_score
