            if i != j:
                states.append((i, j))
    idx = {s: i for i, s in enumerate(states)}
    size = len(states)
    adj = [[0] * size for _ in range(size)]
    for i, (x, y) in enumerate(states):
        for z in range(1, v + 1):
            if z != x and z != y:
                adj[i][idx[(y, z)]] = 1
    def mat_mul(A, B):
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if A[i][k]:
                    for j in range(size):
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C
    def mat_pow(A, p):
        res = [[0] * size for _ in range(size)]
        for i in range(size): res[i][i] = 1
        while p > 0:
            if p % 2 == 1: res = mat_mul(res, A)
            A = mat_mul(A, A)
            p //= 2
        return res
    res_mat = mat_pow(adj, n - 2)
    ans = 0
    for i, (x, y) in enumerate(states):
        for j, (u, v_val) in enumerate(states):
            if y == u and v_val == x:
                ans = (ans + res_mat[i][j]) % MOD
    print(ans)
