def solve():
    constraints = [
        [3, 4, 6, 8], [0, 3, 5, 6, 8], [3, 4, 7, 8],
        [1, 3, 5, 6, 9], [2, 3, 4, 5, 6, 7, 8, 9],
        [0, 10], [1, 11], [0, 1, 2], [4, 5, 10]
    ]
    def get_rank(matrix):
        pivot = 0
        rows = len(matrix)
        cols = 12
        mat = [list(row) for row in matrix]
        for j in range(cols):
            if pivot >= rows: break
            for i in range(pivot, rows):
                if (mat[i][j] if j < len(mat[i]) else 0) == 1:
                    mat[pivot], mat[i] = mat[i], mat[pivot]
                    break
            else: continue
            for i in range(rows):
                if i != pivot and (mat[i][j] if j < len(mat[i]) else 0) == 1:
                    for k in range(cols):
                        mat[i][k] = (mat[i][k] + mat[pivot][k]) % 2
            pivot += 1
        return pivot
    H = [[0]*12 for _ in range(9)]
    for i, row in enumerate(constraints):
        for col in row:
            H[i][col] = 1
    rank = get_rank(H)
    dim = 12 - rank
    codewords = []
    for i in range(1 << 12):
        vec = [(i >> j) & 1 for j in range(12)]
        valid = True
        for row in H:
            s = sum(vec[k] for k in range(12) if row[k])
            if s % 2 != 0:
                valid = False
                break
        if valid: codewords.append(vec)
    B = set()
    for c in codewords:
        for i in range(1 << 12):
            vec = [(i >> j) & 1 for j in range(12)]
            dist = sum(1 for j in range(12) if vec[j] != c[j])
            if dist <= 2:
                B.add(tuple(vec))
    return len(B)
